import { Play } from "lucide-react";
import { useState } from "react";
import { cn } from "@/lib/utils";
import type { ProjectImage } from "@/lib/projects";

function formatDuration(seconds?: number) {
  if (!seconds || !Number.isFinite(seconds)) return null;
  const total = Math.round(seconds);
  const minutes = Math.floor(total / 60);
  return `${minutes}:${String(total % 60).padStart(2, "0")}`;
}

// Grid thumbnail for a video: the JPEG frame generated by the server, or, for videos uploaded
// before thumbnails existed, the video itself paused on the frame at 1 s (only metadata and
// that frame are fetched).
export default function VideoThumbnail({ image, animation }: { image: ProjectImage; animation: boolean }) {
  const [failed, setFailed] = useState(false);
  const duration = formatDuration(image.mediaMetadata?.duration);
  return (
    <div className="relative row-start-1 col-start-1 size-full z-30 bg-black">
      {failed ? null : image.thumbnailUrl ? (
        <>
          {/* Same look as image items: the whole frame over a blurred copy of itself. */}
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src={image.thumbnailUrl} alt="" aria-hidden className="absolute inset-0 size-full scale-110 object-cover blur-md brightness-50" />
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={image.thumbnailUrl}
            alt={image.name}
            loading="lazy"
            onError={() => setFailed(true)}
            className={cn("relative size-full object-contain", animation && "transition-all group-hover:scale-105")}
          />
        </>
      ) : (
        <video
          src={`${image.url}#t=1`}
          preload="metadata"
          muted
          playsInline
          disablePictureInPicture
          tabIndex={-1}
          onError={() => setFailed(true)}
          className={cn("pointer-events-none size-full object-contain", animation && "transition-all group-hover:scale-105")}
        />
      )}
      <div className="pointer-events-none absolute inset-0 flex items-center justify-center">
        <span className="flex size-12 items-center justify-center rounded-full bg-black/55 text-white shadow-lg backdrop-blur-sm">
          <Play className="ml-0.5 size-6 fill-current" />
        </span>
      </div>
      <span className="pointer-events-none absolute left-2 top-2 rounded bg-primary/90 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider text-primary-foreground">
        Vídeo
      </span>
      {duration && (
        <span className="pointer-events-none absolute right-2 top-2 rounded bg-black/70 px-1.5 py-0.5 text-[11px] font-medium tabular-nums text-white">
          {duration}
        </span>
      )}
      <span className="pointer-events-none absolute inset-x-0 bottom-0 truncate bg-gradient-to-t from-black/85 to-transparent px-2 pb-1.5 pt-6 text-xs text-white">
        {image.name}
      </span>
    </div>
  );
}
